import{describe,it,expect}from"vitest";import{spaceData,filterSpaceItems,groupSpaceItemsByCategory,groupSpaceItemsByState,getUniqueStates,getUniqueCategories}from"../../frontend/space/space.js";const REQUIRED_FIELDS=["id","title","state","stateCode","location","category","yearEstablishedOrLaunched","type","description","keyContributions","launchVehicleOrRocket","image","tags"];describe("Indian Space Heritage Data Integrity",()=>{it("contains at least 25 space entries in the dataset",()=>{expect(spaceData.length).toBeGreaterThanOrEqual(25)}),it("every space entry contains all required fields with non-empty values",()=>{spaceData.forEach((e,t)=>{REQUIRED_FIELDS.forEach(a=>{expect(e,`Space item at index ${t} missing field ${a}`).toHaveProperty(a),"tags"===a?(expect(Array.isArray(e.tags)).toBe(!0),expect(e.tags.length).toBeGreaterThan(0)):"yearEstablishedOrLaunched"===a?(expect(typeof e[a]).toBe("number"),expect(e[a]).toBeGreaterThan(1950)):(expect(typeof e[a]).toBe("string"),expect(e[a].trim().length).toBeGreaterThan(0))})})}),it("all space item IDs are unique",()=>{const e=spaceData.map(e=>e.id),t=new Set(e);expect(t.size).toBe(e.length)}),it("all space item titles are unique",()=>{const e=spaceData.map(e=>e.title),t=new Set(e);expect(t.size).toBe(e.length)}),it("covers ISRO launch sites, research centres, tracking centres, satellites, and deep space missions",()=>{const e=new Set(spaceData.map(e=>e.category));expect(e.has("Launch Sites")).toBe(!0),expect(e.has("Research Centres")).toBe(!0),expect(e.has("Tracking Centres")).toBe(!0),expect(e.has("Historic Satellites")).toBe(!0),expect(e.has("Deep Space & Solar")).toBe(!0)}),it("covers multiple Indian states/UTs (Andhra Pradesh, Kerala, Karnataka, Gujarat, Telangana, Tamil Nadu, Odisha, etc.)",()=>{const e=new Set(spaceData.map(e=>e.state));expect(e.size).toBeGreaterThanOrEqual(6)})}),describe("Space Heritage Filtering & Search Algorithms",()=>{it("returns all space items when search query and filters are default",()=>{const e=filterSpaceItems(spaceData);expect(e.length).toBe(spaceData.length)}),it("filters space items by search query (e.g. Chandrayaan)",()=>{const e=filterSpaceItems(spaceData,{search:"Chandrayaan"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{const t=[e.title,e.location,e.state,e.category,e.type,e.description,e.keyContributions,e.launchVehicleOrRocket,...e.tags||[]].some(e=>e&&e.toLowerCase().includes("chandrayaan"));expect(t).toBe(!0)})}),it("filters space items by state code (e.g. ap for Andhra Pradesh)",()=>{const e=filterSpaceItems(spaceData,{state:"ap"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.stateCode).toBe("ap")})}),it("filters space items by category (e.g. Launch Sites)",()=>{const e=filterSpaceItems(spaceData,{category:"launch sites"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.category.toLowerCase()).toBe("launch sites")})}),it("combines search, state, and category filters correctly",()=>{const e=filterSpaceItems(spaceData,{search:"sriharikota",state:"ap",category:"launch sites"});expect(e.length).toBeGreaterThan(0),e.forEach(e=>{expect(e.stateCode).toBe("ap"),expect(e.category.toLowerCase()).toBe("launch sites")})}),it("returns empty array when search query matches no item",()=>{const e=filterSpaceItems(spaceData,{search:"nonexistentspaceitem999"});expect(e.length).toBe(0)}),it("handles invalid or empty inputs gracefully",()=>{expect(filterSpaceItems(null)).toEqual([]),expect(filterSpaceItems(void 0)).toEqual([]),expect(filterSpaceItems([])).toEqual([])})}),describe("Space Heritage Grouping & Helper Functions",()=>{it("groups space items correctly by category",()=>{const e=groupSpaceItemsByCategory(spaceData);expect(e["Launch Sites"]).toBeDefined(),expect(e["Research Centres"]).toBeDefined(),expect(e["Deep Space & Solar"]).toBeDefined()}),it("groups space items correctly by state",()=>{const e=groupSpaceItemsByState(spaceData);expect(e["Andhra Pradesh"]).toBeDefined(),expect(e.Kerala).toBeDefined(),expect(e.Karnataka).toBeDefined()}),it("extracts unique states sorted alphabetically",()=>{const e=getUniqueStates(spaceData);expect(e.length).toBeGreaterThanOrEqual(6),expect(e[0]).toHaveProperty("code"),expect(e[0]).toHaveProperty("name");for(let t=1;t<e.length;t++)expect(e[t-1].name.localeCompare(e[t].name)).toBeLessThanOrEqual(0)}),it("extracts unique categories sorted alphabetically",()=>{const e=getUniqueCategories(spaceData);expect(e.length).toBeGreaterThan(0),expect(e).toContain("Launch Sites"),expect(e).toContain("Research Centres")})});